  // sophisticated.
  let facetName = this.gadgetFacetName(gadgetId);
  let oldChat = this.#runningChatIds.get(gadgetId);
  let newChat = chatId ?? null;
  if (newChat !== oldChat) {
    this.ctx.facets.abort(facetName, new Error(
        newChat === null
