    };

    let unsubscribe = () => {
      this.impl.storage.title.unsubscribe(titleSubscriber);
      this.impl.storage.totalCost.unsubscribe(costSubscriber);
      this.impl.storage.prohibitAllSharing.unsubscribe(sharingProhibitedSubscriber);
